// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title CertificateNFT
 * @dev Soulbound ERC-721 Graduation Certificate Token for BlockLearnX
 * Minted upon course completion with verified quiz scores & AI assignment grades.
 */
contract CertificateNFT {
    string public name = "BlockLearnX Soulbound Certificate";
    string public symbol = "BLX-CERT";

    address public admin;
    uint256 public nextTokenId = 1;

    struct CertificateData {
        string courseTitle;
        string learnerName;
        uint256 score;
        uint256 completionTimestamp;
        string metadataURI;
    }

    mapping(uint256 => address) public ownerOf;
    mapping(address => uint256[]) public learnerCertificates;
    mapping(uint256 => CertificateData) public certificates;

    event CertificateMinted(uint256 indexed tokenId, address indexed learner, string courseTitle, uint256 score);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Only admin can mint certificates");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function mintCertificate(
        address learner,
        string memory courseTitle,
        string memory learnerName,
        uint256 score,
        string memory metadataURI
    ) external onlyAdmin returns (uint256) {
        uint256 tokenId = nextTokenId++;
        ownerOf[tokenId] = learner;
        learnerCertificates[learner].push(tokenId);

        certificates[tokenId] = CertificateData({
            courseTitle: courseTitle,
            learnerName: learnerName,
            score: score,
            completionTimestamp: block.timestamp,
            metadataURI: metadataURI
        });

        emit CertificateMinted(tokenId, learner, courseTitle, score);
        return tokenId;
    }

    function getCertificate(uint256 tokenId) external view returns (CertificateData memory) {
        require(ownerOf[tokenId] != address(0), "Certificate does not exist");
        return certificates[tokenId];
    }

    function getLearnerCertificates(address learner) external view returns (uint256[] memory) {
        return learnerCertificates[learner];
    }

    // Non-transferable (Soulbound) enforcement
    function transferFrom(address, address, uint256) external pure {
        revert("Soulbound: Certificates are non-transferable");
    }
}

contracts/CourseRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title CourseRegistry
 * @dev On-chain course registry & enrollment escrow for BlockLearnX
 * Handles course lifecycle (Draft, Pending Approval, Published),
 * enrollment payments in native token / stablecoins, and provider payouts.
 */
contract CourseRegistry {
    enum CourseStatus { Draft, PendingApproval, Published, Archived }

    struct Course {
        string courseId;
        string title;
        address provider;
        uint256 price; // In wei or token base units
        uint256 rewardPool;
        CourseStatus status;
        uint256 totalEnrollments;
        uint256 totalRevenue;
    }

    address public admin;
    mapping(string => Course) public courses;
    mapping(string => mapping(address => bool)) public isEnrolled;
    string[] public courseIds;

    event CourseRegistered(string indexed courseId, string title, address indexed provider, uint256 price);
    event CourseStatusChanged(string indexed courseId, CourseStatus status);
    event CourseEnrolled(string indexed courseId, address indexed learner, uint256 feePaid);
    event ProviderPayout(address indexed provider, uint256 amount);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Only platform admin");
        _;
    }

    modifier onlyProvider(string memory courseId) {
        require(courses[courseId].provider == msg.sender || msg.sender == admin, "Not authorized provider");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function registerCourse(
        string memory courseId,
        string memory title,
        uint256 price,
        uint256 rewardPool
    ) external {
        require(courses[courseId].provider == address(0), "Course already registered");

        courses[courseId] = Course({
            courseId: courseId,
            title: title,
            provider: msg.sender,
            price: price,
            rewardPool: rewardPool,
            status: CourseStatus.Draft,
            totalEnrollments: 0,
            totalRevenue: 0
        });

        courseIds.push(courseId);
        emit CourseRegistered(courseId, title, msg.sender, price);
    }

    function submitForApproval(string memory courseId) external onlyProvider(courseId) {
        require(courses[courseId].status == CourseStatus.Draft, "Course not in Draft state");
        courses[courseId].status = CourseStatus.PendingApproval;
        emit CourseStatusChanged(courseId, CourseStatus.PendingApproval);
    }

    function approveCourse(string memory courseId) external onlyAdmin {
        require(courses[courseId].status == CourseStatus.PendingApproval, "Not awaiting approval");
        courses[courseId].status = CourseStatus.Published;
        emit CourseStatusChanged(courseId, CourseStatus.Published);
    }

    function enrollInCourse(string memory courseId) external payable {
        Course storage c = courses[courseId];
        require(c.status == CourseStatus.Published, "Course not published");
        require(!isEnrolled[courseId][msg.sender], "Already enrolled");
        require(msg.value >= c.price, "Insufficient enrollment fee");

        isEnrolled[courseId][msg.sender] = true;
        c.totalEnrollments += 1;
        c.totalRevenue += msg.value;

        // Transfer 90% to provider, 10% platform fee
        uint256 providerShare = (msg.value * 90) / 100;
        payable(c.provider).transfer(providerShare);

        emit CourseEnrolled(courseId, msg.sender, msg.value);
        emit ProviderPayout(c.provider, providerShare);
    }

    function getCourseCount() external view returns (uint256) {
        return courseIds.length;
    }
}

contracts/MXToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title MXToken
 * @dev ERC-20 Reward Token for BlockLearnX Decentralized Learning Platform
 * Learners earn MX tokens for completing lessons, passing quizzes, and submitting AI assignments.
 */
contract MXToken {
    string public name = "BlockLearnX MX Token";
    string public symbol = "MX";
    uint8 public decimals = 18;
    uint256 public totalSupply;

    address public owner;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => bool) public authorizedMinters;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event RewardMinted(address indexed learner, uint256 amount, string milestone);
    event MinterAuthorized(address indexed minter);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this");
        _;
    }

    modifier onlyMinter() {
        require(msg.sender == owner || authorizedMinters[msg.sender], "Not authorized to mint rewards");
        _;
    }

    constructor(uint256 initialSupply) {
        owner = msg.sender;
        authorizedMinters[msg.sender] = true;
        mint(msg.sender, initialSupply * 10 ** uint256(decimals));
    }

    function setMinter(address minter, bool authorized) external onlyOwner {
        authorizedMinters[minter] = authorized;
        emit MinterAuthorized(minter);
    }

    function mint(address to, uint256 amount) public onlyMinter returns (bool) {
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
        return true;
    }

    function mintReward(address learner, uint256 amount, string memory milestone) external onlyMinter returns (bool) {
        uint256 value = amount * 10 ** uint256(decimals);
        totalSupply += value;
        balanceOf[learner] += value;
        emit Transfer(address(0), learner, value);
        emit RewardMinted(learner, amount, milestone);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        require(balanceOf[msg.sender] >= value, "Insufficient balance");
        balanceOf[msg.sender] -= value;
        balanceOf[to] += value;
        emit Transfer(msg.sender, to, value);
        return true;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        require(balanceOf[from] >= value, "Insufficient balance");
        require(allowance[from][msg.sender] >= value, "Allowance exceeded");
        balanceOf[from] -= value;
        allowance[from][msg.sender] -= value;
        balanceOf[to] += value;
        emit Transfer(from, to, value);
        return true;
    }
}

